Below is a production-oriented Python research loop using Exa’s official `exa-py` SDK. It keeps durable state, performs iterative search and content retrieval, deduplicates URLs, records evidence, expands a query frontier, enforces budgets, and can resume after a restart. The SDK supports `Exa(...)`, `search`, `search_and_contents`, and `get_contents`; install it with `pip install exa-py`.[1][2]

## Install and configure

```bash
pip install exa-py
export EXA_API_KEY="your_exa_api_key"
```

The code below uses only the Exa SDK and Python’s standard library.

```python
# exa_research_loop.py
from __future__ import annotations

import hashlib
import json
import os
import re
import time
from dataclasses import asdict, dataclass, field
from pathlib import Path
from typing import Any, Iterable

from exa_py import Exa


STATE_VERSION = 1


@dataclass
class Candidate:
    url: str
    title: str | None = None
    published_date: str | None = None
    score: float | None = None
    highlights: list[str] = field(default_factory=list)
    source_query: str = ""
    discovered_at: float = field(default_factory=time.time)


@dataclass
class Evidence:
    url: str
    title: str | None
    accepted: bool
    reason: str
    excerpts: list[str] = field(default_factory=list)
    discovered_entities: list[str] = field(default_factory=list)
    evaluated_at: float = field(default_factory=time.time)


@dataclass
class ResearchState:
    goal: str
    iteration: int = 0
    max_iterations: int = 6
    max_search_calls: int = 12
    max_pages_fetched: int = 48
    max_accepted_items: int = 30
    max_results_per_search: int = 15
    pages_per_iteration: int = 6

    search_calls: int = 0
    pages_fetched: int = 0

    seen_urls: set[str] = field(default_factory=set)
    seen_query_hashes: set[str] = field(default_factory=set)

    query_history: list[str] = field(default_factory=list)
    frontier: list[str] = field(default_factory=list)
    gaps: list[str] = field(default_factory=list)

    candidates: dict[str, Candidate] = field(default_factory=dict)
    accepted: dict[str, Evidence] = field(default_factory=dict)
    rejected: dict[str, Evidence] = field(default_factory=dict)

    no_progress_iterations: int = 0
    status: str = "running"


class JsonStateStore:
    """Small durable state store; replace with Postgres/Redis in production."""

    def __init__(self, state_path: str = "research_state.json"):
        self.path = Path(state_path)

    def save(self, state: ResearchState) -> None:
        payload = asdict(state)
        payload["version"] = STATE_VERSION
        payload["seen_urls"] = sorted(state.seen_urls)
        payload["seen_query_hashes"] = sorted(state.seen_query_hashes)

        payload["candidates"] = {
            url: asdict(candidate)
            for url, candidate in state.candidates.items()
        }
        payload["accepted"] = {
            url: asdict(evidence)
            for url, evidence in state.accepted.items()
        }
        payload["rejected"] = {
            url: asdict(evidence)
            for url, evidence in state.rejected.items()
        }

        temp_path = self.path.with_suffix(".tmp")
        temp_path.write_text(
            json.dumps(payload, indent=2, ensure_ascii=False),
            encoding="utf-8",
        )
        temp_path.replace(self.path)

    def load(self) -> ResearchState:
        payload = json.loads(self.path.read_text(encoding="utf-8"))

        if payload.get("version") != STATE_VERSION:
            raise ValueError("Unsupported research-state version")

        candidates = {
            url: Candidate(**value)
            for url, value in payload.get("candidates", {}).items()
        }
        accepted = {
            url: Evidence(**value)
            for url, value in payload.get("accepted", {}).items()
        }
        rejected = {
            url: Evidence(**value)
            for url, value in payload.get("rejected", {}).items()
        }

        return ResearchState(
            goal=payload["goal"],
            iteration=payload.get("iteration", 0),
            max_iterations=payload.get("max_iterations", 6),
            max_search_calls=payload.get("max_search_calls", 12),
            max_pages_fetched=payload.get("max_pages_fetched", 48),
            max_accepted_items=payload.get("max_accepted_items", 30),
            max_results_per_search=payload.get("max_results_per_search", 15),
            pages_per_iteration=payload.get("pages_per_iteration", 6),
            search_calls=payload.get("search_calls", 0),
            pages_fetched=payload.get("pages_fetched", 0),
            seen_urls=set(payload.get("seen_urls", [])),
            seen_query_hashes=set(payload.get("seen_query_hashes", [])),
            query_history=payload.get("query_history", []),
            frontier=payload.get("frontier", []),
            gaps=payload.get("gaps", []),
            candidates=candidates,
            accepted=accepted,
            rejected=rejected,
            no_progress_iterations=payload.get("no_progress_iterations", 0),
            status=payload.get("status", "running"),
        )


def normalize_url(url: str) -> str:
    """Remove fragments and common tracking parameters for deduplication."""
    url = url.strip()
    url = url.split("#", 1)[0]

    if "?" not in url:
        return url.rstrip("/")

    base, query = url.split("?", 1)
    keep = []

    for parameter in query.split("&"):
        name = parameter.split("=", 1)[0].lower()
        if name.startswith("utm_"):
            continue
        if name in {"gclid", "fbclid", "mc_cid", "mc_eid"}:
            continue
        keep.append(parameter)

    return f"{base.rstrip('/')}?{'&'.join(keep)}" if keep else base.rstrip("/")


def stable_hash(value: str) -> str:
    return hashlib.sha256(value.strip().lower().encode("utf-8")).hexdigest()


def text_from_result(result: Any) -> str:
    text = getattr(result, "text", None) or ""
    highlights = getattr(result, "highlights", None) or []

    if isinstance(highlights, list):
        highlight_text = "\n".join(str(item) for item in highlights)
    else:
        highlight_text = str(highlights)

    return f"{text}\n{highlight_text}".strip()


def useful_excerpt(text: str, max_chars: int = 500) -> str:
    text = re.sub(r"\s+", " ", text).strip()
    return text[:max_chars]


class ExaResearchLoop:
    def __init__(
        self,
        exa: Exa,
        state: ResearchState,
        store: JsonStateStore,
    ):
        self.exa = exa
        self.state = state
        self.store = store

    def should_stop(self) -> bool:
        s = self.state

        if s.iteration >= s.max_iterations:
            s.status = "stopped_max_iterations"
            return True

        if s.search_calls >= s.max_search_calls:
            s.status = "stopped_search_budget"
            return True

        if s.pages_fetched >= s.max_pages_fetched:
            s.status = "stopped_page_budget"
            return True

        if len(s.accepted) >= s.max_accepted_items:
            s.status = "stopped_target_reached"
            return True

        if s.no_progress_iterations >= 2:
            s.status = "stopped_saturated"
            return True

        return False

    def plan_next_query(self) -> str:
        s = self.state

        if s.iteration == 0:
            return s.goal

        if s.gaps:
            gap = s.gaps.pop(0)
            return f"{s.goal}. Focus specifically on: {gap}"

        if s.frontier:
            seed = s.frontier.pop(0)
            return (
                f"{s.goal}. Find primary sources, official pages, technical "
                f"documentation, repositories, competitors, citations, or "
                f"directly related entities associated with: {seed}"
            )

        return (
            f"{s.goal}. Find additional primary sources and entities not "
            f"already covered by earlier research."
        )

    def search(self, query: str) -> list[Candidate]:
        s = self.state
        query_hash = stable_hash(query)

        if query_hash in s.seen_query_hashes:
            return []

        s.seen_query_hashes.add(query_hash)
        s.query_history.append(query)
        s.search_calls += 1

        response = self.exa.search(
            query,
            type="auto",
            num_results=s.max_results_per_search,
            contents={
                "highlights": {
                    "max_characters": 800
                }
            },
        )

        new_candidates: list[Candidate] = []

        for result in response.results:
            raw_url = getattr(result, "url", None)
            if not raw_url:
                continue

            url = normalize_url(raw_url)
            if url in s.seen_urls:
                continue

            s.seen_urls.add(url)

            highlights = getattr(result, "highlights", None) or []
            if not isinstance(highlights, list):
                highlights = [str(highlights)]

            candidate = Candidate(
                url=url,
                title=getattr(result, "title", None),
                published_date=getattr(result, "published_date", None),
                score=getattr(result, "score", None),
                highlights=[str(item) for item in highlights if item],
                source_query=query,
            )

            s.candidates[url] = candidate
            new_candidates.append(candidate)

        return new_candidates

    def choose_pages_to_fetch(
        self,
        candidates: Iterable[Candidate],
    ) -> list[Candidate]:
        remaining_budget = self.state.max_pages_fetched - self.state.pages_fetched
        limit = min(self.state.pages_per_iteration, remaining_budget)

        ranked = sorted(
            candidates,
            key=lambda c: (
                c.score is not None,
                c.score or float("-inf"),
                len(c.highlights),
            ),
            reverse=True,
        )

        return ranked[:max(limit, 0)]

    def fetch_pages(self, candidates: list[Candidate]) -> list[Any]:
        if not candidates:
            return []

        urls = [candidate.url for candidate in candidates]

        response = self.exa.get_contents(
            urls,
            text={"max_characters": 8000},
            highlights=True,
        )

        self.state.pages_fetched += len(urls)
        return list(response.results)

    def evaluate_page(self, page: Any) -> Evidence:
        """
        Replace this baseline evaluator with a structured LLM judge,
        domain-specific rules, or human review for high-stakes workflows.
        """
        url = normalize_url(getattr(page, "url", ""))
        title = getattr(page, "title", None)
        text = text_from_result(page)

        candidate = self.state.candidates.get(url)
        source_query = candidate.source_query if candidate else self.state.goal

        lower_text = text.lower()
        goal_terms = [
            term.lower()
            for term in re.findall(r"[A-Za-z][A-Za-z0-9_-]{3,}", self.state.goal)
        ]

        matched_terms = [
            term for term in goal_terms
            if term in lower_text
        ]

        has_substance = len(text) >= 500
        topical_match = len(matched_terms) >= max(1, min(2, len(goal_terms)))
        accepted = has_substance and topical_match

        excerpts = []
        highlights = getattr(page, "highlights", None) or []
        if isinstance(highlights, list):
            excerpts.extend(
                useful_excerpt(str(item), 500)
                for item in highlights[:4]
                if item
            )

        if not excerpts and text:
            excerpts = [useful_excerpt(text, 700)]

        discovered_entities = self.extract_frontier_terms(
            title=title or "",
            text=text,
            source_query=source_query,
        )

        if accepted:
            reason = (
                f"Substantive content found with matched goal terms: "
                f"{', '.join(matched_terms[:6])}"
            )
        else:
            reason = (
                f"Rejected: has_substance={has_substance}, "
                f"matched_goal_terms={matched_terms[:6]}"
            )

        return Evidence(
            url=url,
            title=title,
            accepted=accepted,
            reason=reason,
            excerpts=excerpts,
            discovered_entities=discovered_entities,
        )

    def extract_frontier_terms(
        self,
        title: str,
        text: str,
        source_query: str,
    ) -> list[str]:
        """
        Conservative query-expansion heuristic. In production, ask a
        structured evaluator for canonical entities, synonyms, missing facts,
        and follow-up queries.
        """
        corpus = f"{title}\n{text[:2500]}"
        phrases = re.findall(
            r"\b(?:[A-Z][a-zA-Z0-9&.-]+(?:\s+[A-Z][a-zA-Z0-9&.-]+){0,3})\b",
            corpus,
        )

        blocked = {
            "The", "This", "That", "With", "From", "About", "Home",
            "Contact", "Privacy", "Terms", "Cookie", "Cookies",
        }

        seen = set()
        terms = []

        for phrase in phrases:
            phrase = phrase.strip()
            if phrase in blocked or len(phrase) < 4:
                continue

            normalized = phrase.lower()
            if normalized in seen:
                continue

            if normalized in source_query.lower():
                continue

            seen.add(normalized)
            terms.append(phrase)

            if len(terms) >= 3:
                break

        return terms

    def update_state(self, evidence_items: list[Evidence]) -> int:
        newly_accepted = 0

        for evidence in evidence_items:
            if evidence.accepted:
                if evidence.url not in self.state.accepted:
                    newly_accepted += 1

                self.state.accepted[evidence.url] = evidence

                for term in evidence.discovered_entities:
                    if term not in self.state.frontier:
                        self.state.frontier.append(term)
            else:
                self.state.rejected[evidence.url] = evidence

        return newly_accepted

    def run_iteration(self) -> None:
        if self.should_stop():
            self.store.save(self.state)
            return

        self.state.iteration += 1
        query = self.plan_next_query()

        candidates = self.search(query)
        pages_to_fetch = self.choose_pages_to_fetch(candidates)
        pages = self.fetch_pages(pages_to_fetch)
        assessments = [self.evaluate_page(page) for page in pages]

        newly_accepted = self.update_state(assessments)

        if newly_accepted == 0:
            self.state.no_progress_iterations += 1
        else:
            self.state.no_progress_iterations = 0

        self.store.save(self.state)

    def run(self) -> ResearchState:
        while not self.should_stop():
            self.run_iteration()

        self.store.save(self.state)
        return self.state


def persist_state(state: ResearchState) -> None:
    """Optional hook for database persistence, metrics, or event publishing."""
    return None


def main() -> None:
    api_key = os.environ.get("EXA_API_KEY")
    if not api_key:
        raise RuntimeError("Set EXA_API_KEY before running this script.")

    store = JsonStateStore("research_state.json")

    if store.path.exists():
        state = store.load()
    else:
        state = ResearchState(
            goal=(
                "Find open-source Python libraries for constrained "
                "Bayesian optimization, emphasizing official documentation "
                "and source repositories."
            ),
            max_iterations=6,
            max_search_calls=10,
            max_pages_fetched=36,
            max_accepted_items=20,
        )

    exa = Exa(api_key=api_key)
    loop = ExaResearchLoop(exa=exa, state=state, store=store)
    final_state = loop.run()

    print(json.dumps({
        "status": final_state.status,
        "iterations": final_state.iteration,
        "search_calls": final_state.search_calls,
        "pages_fetched": final_state.pages_fetched,
        "accepted_count": len(final_state.accepted),
        "accepted": [
            {
                "url": item.url,
                "title": item.title,
                "reason": item.reason,
                "excerpts": item.excerpts,
            }
            for item in final_state.accepted.values()
        ],
    }, indent=2, ensure_ascii=False))


if __name__ == "__main__":
    main()
```

## How the loop works

The loop is deliberately stateful:

\[
\text{persisted state}
\rightarrow
\text{query planner}
\rightarrow
\text{Exa search}
\rightarrow
\text{content extraction}
\rightarrow
\text{evaluation}
\rightarrow
\text{state update}
\rightarrow
\text{next query}
\]

Each iteration:

1. Chooses a new query from the research goal, known gaps, or entity/topic frontier.
2. Calls `exa.search(...)` to discover candidate URLs.
3. Normalizes and deduplicates URLs.
4. Fetches only the strongest new candidates with `exa.get_contents(...)`.
5. Evaluates pages and saves excerpts as evidence.
6. Extracts potential follow-up entities/topics.
7. Persists all state atomically to JSON.
8. Stops when it hits completion, saturation, result, page, call, or iteration limits.

The Exa Python SDK supports the exact primitives used here: `search`, `search_and_contents`, and `get_contents`. It also supports requesting text, highlights, and configurable content options.[2][1]

## Improve the evaluator

The included `evaluate_page()` function is intentionally conservative and simple. For a serious agent, make it return strict JSON from a model or a domain-specific rule engine:

```python
{
    "accept": true,
    "entity_type": "open_source_python_library",
    "canonical_name": "BoTorch",
    "official_url": "",
    "repository_url": "",
    "criteria": {
        "open_source": {"value": true, "evidence": "..."},
        "python_library": {"value": true, "evidence": "..."},
        "constrained_bayesian_optimization": {
            "value": true,
            "evidence": "..."
        }
    },
    "follow_up_queries": [
        "BoTorch constrained Bayesian optimization documentation",
        "BoTorch inequality constraints GitHub"
    ],
    "confidence": 0.93
}
```

Then update the state only from structured output:

```python
def apply_structured_evaluation(
    state: ResearchState,
    decision: dict[str, Any],
) -> None:
    url = normalize_url(decision["official_url"])

    evidence = Evidence(
        url=url,
        title=decision.get("canonical_name"),
        accepted=bool(decision["accept"]),
        reason=json.dumps(decision["criteria"], ensure_ascii=False),
        excerpts=[
            criterion["evidence"]
            for criterion in decision["criteria"].values()
            if criterion.get("evidence")
        ],
        discovered_entities=decision.get("follow_up_queries", []),
    )

    if evidence.accepted:
        state.accepted[url] = evidence
        state.frontier.extend(
            query for query in decision.get("follow_up_queries", [])
            if query not in state.frontier
        )
    else:
        state.rejected[url] = evidence
```

## Using `search_and_contents`

For a compact prototype, Exa’s SDK can retrieve result metadata and page content in one call:

```python
from exa_py import Exa
import os

exa = Exa(api_key=os.environ["EXA_API_KEY"])

response = exa.search_and_contents(
    "Open-source Python libraries for constrained Bayesian optimization",
    type="auto",
    num_results=10,
    text={"max_characters": 6000},
    highlights={
        "highlights_per_url": 3,
        "num_sentences": 2,
    },
)

for result in response.results:
    print(result.title)
    print(result.url)
    print((result.text or "")[:500])
```

Use this form when most top results deserve inspection. Use separate `search` then `get_contents` calls when pages are expensive to fetch and you need a controller to choose only a small shortlist. Both patterns are supported by Exa’s official SDK.[1][2]

## Resume after interruption

Because the loop writes `research_state.json` after each iteration, restart it normally:

```bash
python exa_research_loop.py
```

It will:

- Retain prior accepted and rejected URLs.
- Avoid repeating normalized queries.
- Avoid fetching already seen pages.
- Continue from the stored frontier and gaps.
- Preserve page/search budgets.
- Stop once an existing termination rule is met.

For production, replace `JsonStateStore` with a transactional datastore and key state by:

```text
tenant_id / user_id / research_job_id
```

Store the following separately:

| Data | Why retain it |
|---|---|
| Research goal and constraints | Rebuild planner context |
| Query history | Prevent query loops |
| Normalized URL set | Prevent duplicate fetches |
| Accepted/rejected records | Keep decisions stable |
| Evidence excerpts | Explain inclusion |
| Entity aliases and canonical IDs | Deduplicate different URLs for one entity |
| Frontier queue | Resume expansion |
| Budget counters | Enforce cost and time limits |
| Model/evaluator version | Re-evaluate only when needed |

## Exa Agent continuation

For more autonomous, bounded multi-step research, use Exa’s Agent API and save the returned run ID. Later tasks can pass `previousRunId` so the new run builds on the completed run’s context.[3]

Conceptually:

```python
first_run = exa.agent.runs.create(
    query="Find 30 relevant open-source Python libraries...",
    effort="high",
)

# Persist first_run.id in your own state store.

follow_up_run = exa.agent.runs.create(
    previous_run_id=first_run.id,
    query=(
        "Keep only libraries with explicit support for constrained "
        "Bayesian optimization. Return repository URL and evidence."
    ),
    effort="medium",
)
```

Use your own outer state machine even when using `previousRunId`: it should decide whether another run is justified, enforce budgets, retain accepted entities, and avoid recursive follow-ups with no new information.
